# manually tested

import ollama

# Send a prompt to the locally running Llama 3.2 model.
response = ollama.chat(
    model="llama3.2:3b",
    messages=[
        {
            # Define the message as a user prompt.
            "role": "user",
            "content": "Explain RAG in simple terms"
        }
    ]
)

# Print the response generated by the LLM.
print(response.message.content)
